208	        // Any other protected path that is not a regular file (a link whose target would be read through, a special
209	        // file, a directory in its place) cannot be compared: nothing new is kept because of it.
210	        if (!structural) complete = false;
211	        continue;
212	      }
213	      size = st.size;
214	    } catch (err: any) {
215	      // Gone from disk: there is nothing to copy from it (a deleted protected path is a protected change, handled by the caller).
216	      if (err?.code !== "ENOENT") complete = false;
217	      continue;
218	    }
219	    // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
220	    if (structural && size > SOURCE_FILE_MAX) continue;
221	    if (!structural) total += size;
222	    if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
223	    let data: Buffer;
224	    try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
225	    hashes.add(createHash("sha256").update(data).digest("hex"));
226	    if (structural) continue;
227	    for (const line of significantLines(data)) lines.add(line);
228	  }
229	  return {
230	    carriedBy(dir: string, relative: string): boolean {
231	      if (!complete) return true;
232	      if (hashes.size === 0 && lines.size === 0) return false;
233	      let data: Buffer;
234	      try {
235	        const st = fs.lstatSync(path.join(dir, relative));
236	        // A link is shown as its target path, never as content; anything else that is not a regular file is not read.
237	        if (!st.isFile()) return !st.isSymbolicLink();
238	        if (st.size > ADDED_FILE_MAX) return true;
239	        data = fs.readFileSync(path.join(dir, relative));
240	      } catch { return true; }
241	      if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
242	      for (const line of significantLines(data)) if (lines.has(line)) return true;
243	      return false;
244	    },
245	  };
246	}
247	
248	function significantLines(data: Buffer): string[] {
249	  return data.toString("latin1").split("\n").map((l) => l.trim())
250	    .filter((l) => l.length >= SIGNIFICANT_LINE_MIN && !l.startsWith("#") && !l.startsWith("//") && /[A-Za-z0-9]/.test(l));
251	}
