253	/**
254	 * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
255	 * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
256	 */
257	export function attributesTree(root: string, scratch: string, files: string[], pin: string[]): { tree: string; objects: string } | undefined {
258	  const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
259	    try {
260	      const full = path.join(root, f);
261	      const st = fs.lstatSync(full);
262	      return st.isFile() && st.size <= MAX_ATTRIBUTES_BYTES ? [{ file: f, text: withoutDrivers(fs.readFileSync(full, "utf8")) }] : [];
263	    } catch { return []; }
264	  });
265	  if (!sources.length) return undefined;
266	  const objects = path.join(scratch, "attr-objects");
267	  fs.mkdirSync(objects);
268	  const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
269	  const run = (args: string[], input?: string) => execFileSync("git", [...pin, ...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: 30_000, ...(input === undefined ? {} : { input }) });
270	  const entries = sources.map(({ file, text }) => `100644 ${run(["hash-object", "-w", "--stdin"], text).trim()}\t${file}\0`);
271	  run(["update-index", "--add", "-z", "--index-info"], entries.join(""));
272	  return { tree: run(["write-tree"]).trim(), objects };
273	}
274	
275	export interface CandidateDiff { base: string; diff: string; omitted: number; omittedNew: number; omittedNested: number }
276	/** A refusal because the repository state is outside the supported domain (as opposed to a git failure). */
277	export type CandidateDiffError = { error: string; unsupported?: string };
278	
279	/**
280	 * The candidate diff against `base` (HEAD when absent), for every unit that is shown one: review units and the
281	 * security reviewer. No repository-configured command runs while it is built (see GIT_SAFE and safeGitEnv); a
282	 * filter or diff driver that would still apply makes it fail. It is built from the changed paths and never from parsing diff text: the changed paths come from
283	 * NUL-separated git output with rendering options pinned, the protected ones (the read_file policy, `.nexus`) are
284	 * removed, and the diff is then requested for the remaining paths only (literal pathspecs), so a protected file cannot
285	 * appear in it whatever the repository's diff settings. A rename or copy with either side protected drops both sides
286	 * (the body of a file renamed out of a protected path is still its content).
287	 *
288	 * Untracked files are compared through a scratch index (the base tree plus intent-to-add entries for every untracked
289	 * file, never the repository's own index), so git's rename detection pairs an unstaged move of a protected file with
290	 * its new name instead of showing that name as an unrelated new file. Rename and copy detection stop at git's
291	 * similarity threshold (and `--find-copies-harder` makes an untouched tracked protected file a copy source), so when
292	 * any protected path changed (moved, deleted, edited or added), every added file is omitted too and counted in
293	 * `omittedNew`: a protected file moved and rewritten, or one whose lines were copied out, may otherwise reach the diff
294	 * as an innocent new file. Independently of git's heuristics, an added file is omitted (and counted the same way) when
295	 * it equals a protected file present in the workspace, tracked, untracked or ignored, or shares a significant line
296	 * with one (see `protectedContent`); that covers `cp .env notes.txt` and a partial copy of any size.
297	 * Limits of that comparison, where credential redaction is the only guard: lines pasted from a protected file into a
298	 * file that already existed at the base (modified files are not line-compared); any re-formatting of a protected
299	 * file's lines (quoting, a changed separator, values only, re-encoding), because a line matches only exactly once
300	 * trimmed and is at least 8 characters; and a protected file whose lines are all shorter than that, which is caught
301	 * only by an exact whole-file match. The trade-off is over-omission: a new file sharing a common line (such as
302	 * NODE_ENV=development) with any protected file in the workspace, an ignored `.env*` included, is omitted and noted.
303	 * The pass listing ignored files takes up to IGNORED_LISTING_TIMEOUT_MS (about 6 s per 90k ignored files); a tree too
304	 * large for it fails closed with an error rather than being trusted.
305	 * Any git failure or an unmanageable path count returns an error: nothing is ever kept because it could not be
306	 * classified.
307	 */
308	export function candidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | CandidateDiffError {
309	  const root = path.resolve(workspace);
310	  let scratch: string | undefined;
311	  let attrs: { tree: string; objects: string } | undefined;
312	  let pin: string[] = [];
313	  // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
314	  const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
315	    try {
316	      return execFileSync("git", [...pin, ...GIT_SAFE, ...args], {
317	        cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
318	        timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
319	      });
320	    } catch (err: any) {
321	      if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
322	      throw err;
323	    }
324	  };
325	  try {
326	    // Host-side git runs only where the checkout is trusted (the agent may have replaced `.git` or planted a repository),
327	    // and then against the verified git dir and work tree.
328	    pin = trustedGitArgs(root);
329	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
330	    // The policy is the operator's (their workspace), not whatever a unit's own worktree holds: an untracked
331	    // .nexus-security.json never reaches a worktree.
332	    const security = new SecurityManager(policyWorkspace ?? root);
333	    // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
334	    const support = snapshotSupport((args) => git(args, { ownIndex: true, maxBuffer: LISTING_MAX_BUFFER }), root);
335	    if ("unsupported" in support) return { error: `automatic inputs are not available for this repository state: ${support.unsupported}; give the unit explicit inputs instead`, unsupported: support.unsupported };
336	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
337	    git(["read-tree", "--end-of-options", commit]);
338	    const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
339	    // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
340	    // can match .gitignore and still be part of the candidate).
341	    const atBase = new Set(listing([]));
342	    // A path tracked since the base but already removed from disk is a deletion against nothing: it has no content to
343	    // show, and git would reject it as a pathspec.
344	    const onDisk = (p: string) => { try { fs.lstatSync(path.join(root, p)); return true; } catch { return false; } };
345	    const ownIndex = new Set(listing([], true));
346	    // Untracked, non-ignored entries, listed once. A directory entry (trailing slash) is an untracked nested git
347	    // repository, which `git add` refuses: it is skipped and counted rather than failing every review.
348	    const others = listing(["--others", "--exclude-standard"]);
349	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
350	    const untracked = others.filter((p) => !p.endsWith("/"));
351	    attrs = attributesTree(root, scratch, [...new Set([...untracked, ...ownIndex])], pin);
352	    // A path tracked at the base but removed from the real index (`git rm --cached`) is part of the candidate as a
353	    // deletion even when the file stays on disk: force it out of the scratch index too (its entry can match neither HEAD nor the worktree), and never re-add it as new.
354	    const removed = [...atBase].filter((p) => !ownIndex.has(p));
355	    if (removed.length) {
356	      git(["--literal-pathspecs", "rm", "--cached", "--force", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${removed.join("\0")}\0` });
357	    }
358	    const removedSet = new Set(removed);
359	    const added = new Set([
360	      ...untracked.filter((p) => !removedSet.has(p)),
361	      ...[...ownIndex].filter((p) => !atBase.has(p) && onDisk(p)),
362	    ]);
363	    if (added.size) {
364	      git(["--literal-pathspecs", "add", "--force", "--intent-to-add", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${[...added].join("\0")}\0` });
365	    }
366	    // Comparing worktree content runs a path's clean filter, so before any diff every path is checked for a filter or
367	    // diff driver the stripped attribute source did not neutralise ($GIT_DIR/info/attributes, or a worktree
368	    // .gitattributes on Git before 2.40); one that applies is refused, never run. The check is batched so the
369	    // repository's size never turns into a failure.
370	    const refusal = driverRefusal((args, input) => git(args, { input }), listing([]));
371	    if (refusal) return { error: refusal };
372	    // name-status with rename detection (no limit on the exhaustive pass), only to learn which paths belong together.
373	    const tokens = git(["diff", "--name-status", "-z", "-M", "-C", "--find-copies-harder", "-l0", "--relative", "--no-ext-diff", "--no-textconv", "--end-of-options", commit, "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0");
374	    const groups: Array<{ status: string; paths: string[] }> = [];
375	    for (let i = 0; i < tokens.length; ) {
376	      const status = tokens[i++];
377	      if (!status) continue;
378	      const count = status[0] === "R" || status[0] === "C" ? 2 : 1;
379	      const paths = tokens.slice(i, i + count);
380	      i += count;
381	      if (paths.length !== count || paths.some((p) => !p)) return { error: "git reported a changed path that could not be read" };
382	      groups.push({ status, paths });
383	    }
384	    if (groups.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
385	    const isProtected = (group: { paths: string[] }) => group.paths.some((p) => inputPathProtection(security, p) !== undefined);
386	    const protectedChanged = groups.some(isProtected);
387	    // Git's copy detection stops at its similarity threshold and never sees an ignored protected file, so an added file
388	    // is also compared with the content of every protected file present in the workspace.
389	    const sources = protectedMatcher((args, timeoutMs) => git(args, { maxBuffer: LISTING_MAX_BUFFER, timeoutMs }), root, policyWorkspace, security, [...atBase, ...ownIndex, ...untracked]);
390	    let omitted = 0;
391	    let omittedNew = 0;
392	    const allowed: string[] = [];
393	    for (const group of groups) {
394	      if (isProtected(group)) omitted++;
395	      // A copy or rename is a new file too: its destination is compared with the protected content like an added file.
396	      else if ("ACR".includes(group.status[0]) && ((group.status[0] === "A" && protectedChanged) || sources.carriedBy(root, group.paths[group.paths.length - 1]))) omittedNew++;
397	      else allowed.push(...group.paths);
398	    }
399	    const diff = allowed.length ? git(["diff", ...DIFF_FLAGS, "--end-of-options", commit, "--", ...allowed.map((p) => `:(literal)${p}`)]) : "";
400	    return { base: commit, diff, omitted, omittedNew, omittedNested };
401	  } catch (err: any) {
402	    if (err instanceof UntrustedCheckoutError) return { error: `automatic inputs are not available: ${err.message}` };
403	    if (err?.code === "ENOBUFS" || /ENOBUFS/.test(String(err?.message))) {
404	      return { error: `the candidate diff is too large to show (over ${GIT_MAX_BUFFER / (1024 * 1024)} MiB); scope it with explicit inputs` };
405	    }
406	    return { error: `git could not produce the diff (${String(err?.message ?? err).split("\n")[0].slice(0, 120)})` };
407	  } finally {
408	    if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
409	  }
410	}
411	
412	/**
413	 * The comparison of new files with the protected files present in the workspace: tracked, untracked and ignored (listed
414	 * through `git`, a pinned call in the workspace), plus the operator's own when the unit runs in another worktree. A
415	 * failure (timeout, buffer) propagates: the comparison is never silently skipped.
416	 */
417	function protectedMatcher(git: (args: string[], timeoutMs?: number) => string, root: string, policyWorkspace: string | undefined, security: SecurityManager, known: Iterable<string>): ReturnType<typeof protectedContent> {
418	  const ignored = git(["ls-files", "-z", "--others", "--ignored", "--exclude-standard"], IGNORED_LISTING_TIMEOUT_MS).split("\0").filter((p) => p && !p.endsWith("/"));
419	  const protectedSources = [...new Set([...known, ...ignored])]
420	    .filter((p) => inputPathProtection(security, p) !== undefined).map((file) => ({ root, file }));
421	  // A unit's worktree lacks the operator's untracked and ignored secrets (.env), so those are compared too.
422	  if (path.resolve(policyWorkspace ?? root) !== root) {
423	    const operator = path.resolve(policyWorkspace!);
424	    // The operator's own checkout is not agent-writable: it is pinned like any checkout, but a repository nested in it (an untracked clone) is normal there.
425	    const operatorCheckout = verifyCheckout(operator);
426	    if (operatorCheckout.reason) throw new UntrustedCheckoutError(operator, operatorCheckout.reason, []);
427	    const operatorPin = operatorCheckout.gitDir ? ["--git-dir", operatorCheckout.gitDir, "--work-tree", operatorCheckout.workTree!] : [];
428	    for (const extra of [[], ["--ignored"]]) {
429	      const listed = execFileSync("git", [...operatorPin, ...GIT_SAFE, "ls-files", "-z", "--cached", "--others", ...extra, "--exclude-standard"], {
430	        cwd: operator, env: safeGitEnv(undefined), encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: IGNORED_LISTING_TIMEOUT_MS, maxBuffer: LISTING_MAX_BUFFER,
431	      }).split("\0").filter((p) => p && !p.endsWith("/") && inputPathProtection(security, p) !== undefined);
432	      for (const file of listed) protectedSources.push({ root: operator, file });
433	    }
434	  }
435	  return protectedContent(protectedSources);
436	}
437	
438	/**
439	 * A plain candidate diff for review units when the repository state is outside the supported domain: tracked changes
440	 * against the base (`git diff`, no copy detection, no scratch index) plus untracked files. The same
441	 * guards apply that do not depend on the domain: the checkout is verified and pinned, no driver runs, protected paths
442	 * are left out, and a new file carrying protected content is omitted. It can be wrong where the predicate refuses (a
443	 * sparse checkout shows its absent files as deleted, an LFS pointer differs from its content), which is why the reviewer
444	 * is told it is a plain diff.
445	 */
446	export function plainCandidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | { error: string } {
447	  const root = path.resolve(workspace);
448	  let scratch: string | undefined;
449	  try {
450	    const pin = trustedGitArgs(root);
451	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-plain-index-"));
452	    const env = safeGitEnv(path.join(scratch, "index"));
453	    const ownEnv = safeGitEnv(undefined);
454	    const git = (args: string[], options: { okExit?: number[]; timeoutMs?: number; maxBuffer?: number; ownIndex?: boolean; input?: string } = {}): string => {
455	      try {
456	        return execFileSync("git", [...pin, ...GIT_SAFE, ...args], { cwd: root, env: options.ownIndex ? ownEnv : env, encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }) });
457	      } catch (err: any) {
458	        if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
459	        throw err;
460	      }
461	    };
462	    const security = new SecurityManager(policyWorkspace ?? root);
463	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
464	    // The base tree in a private index: no flag of the real index (skip-worktree, assume-unchanged) can hide a file.
465	    git(["read-tree", "--end-of-options", commit]);
466	    // A path the real index no longer holds (`git rm --cached`, the file may stay on disk, ignored) is a deletion of the
467	    // candidate: take it out of the private index too, so the comparison with the base tree still reports it.
468	    const staged = git(["diff-index", "--cached", "--name-status", "-z", "--no-renames", commit], { ownIndex: true, maxBuffer: LISTING_MAX_BUFFER }).split("\0");
469	    const stagedRemovals: string[] = [];
470	    for (let i = 0; i + 1 < staged.length; i += 2) if (staged[i] === "D") stagedRemovals.push(staged[i + 1]);
471	    if (stagedRemovals.length) git(["update-index", "--force-remove", "-z", "--stdin"], { input: `${stagedRemovals.join("\0")}\0` });
472	    // No content is compared (no clean filter can run) before every path is known to have no driver.
473	    const driverCheck = (files: string[]) => driverRefusal((args, input) => execFileSync("git", [...pin, ...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", input, stdio: ["pipe", "pipe", "pipe"], timeout: 30_000, maxBuffer: GIT_MAX_BUFFER }), files);
474	    const listed = [...git(["ls-files", "-z", "--cached"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0"), ...git(["ls-files", "-z", "--others", "--exclude-standard"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0")].filter((p) => p && !p.endsWith("/"));
475	    const early = driverCheck(listed);
476	    if (early) return { error: early };
477	    const tracked = git(["diff", "--name-only", "-z", ...DIFF_RENDER, "--ignore-submodules=all", "--relative", "--no-renames", "--end-of-options", commit, "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0").filter(Boolean);
478	    const others = git(["ls-files", "-z", "--others", "--exclude-standard"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0").filter(Boolean);
479	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
480	    const untracked = others.filter((p) => !p.endsWith("/"));
481	    // A name that is not valid UTF-8 was mangled by decoding and would match nothing: say so instead of dropping the change.
482	    if ([...tracked, ...others].some((p) => p.includes("\uFFFD"))) return { error: "a changed path is not valid UTF-8 text and cannot be shown; rename it" };
483	    if (tracked.length + untracked.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
484	    const allowedTracked = tracked.filter((p) => inputPathProtection(security, p) === undefined);
485	    const sources = protectedMatcher((args, timeoutMs) => git(args, { maxBuffer: LISTING_MAX_BUFFER, timeoutMs }), root, policyWorkspace, security, [...tracked, ...untracked]);
486	    let omitted = tracked.length - allowedTracked.length;
487	    let omittedNew = 0;
488	    const allowedNew: string[] = [];
489	    // As in the main builder: once any protected path changed (a protected file moved leaves no source on disk), no new file is shown.
490	    const protectedChanged = allowedTracked.length !== tracked.length;
491	    for (const file of untracked) {
492	      if (inputPathProtection(security, file) !== undefined) omitted++;
493	      else if (protectedChanged || sources.carriedBy(root, file)) omittedNew++;
494	      else allowedNew.push(file);
495	    }
496	    let diff = allowedTracked.length ? git(["diff", ...DIFF_RENDER, "--no-renames", "--ignore-submodules=all", "--relative", "--end-of-options", commit, "--", ...allowedTracked.map((p) => `:(literal)${p}`)]) : "";
497	    for (const file of allowedNew) diff += git(["diff", ...DIFF_RENDER, "--no-index", "--", "/dev/null", file], { okExit: [1] });
498	    return { base: commit, diff, omitted, omittedNew, omittedNested };
499	  } catch (err: any) {
500	    if (err instanceof UntrustedCheckoutError) return { error: `automatic inputs are not available: ${err.message}` };
501	    if (err?.code === "ENOBUFS" || /ENOBUFS/.test(String(err?.message))) return { error: `the candidate diff is too large to show (over ${GIT_MAX_BUFFER / (1024 * 1024)} MiB)` };
502	    return { error: `git could not produce the diff (${String(err?.message ?? err).split("\n")[0].slice(0, 120)})` };
503	  } finally {
504	    if (scratch) fs.rmSync(scratch, { recursive: true, force: true });
505	  }
506	}
507	
508	/** Credential-redacted and bounded to the input limit, with a marker when cut. */
509	export function boundedRedactedInput(text: string): string {
510	  const redacted = redactForPersistence(text);
511	  return redacted.length > MAX_SPECIALIST_INPUT_CHARS ? `${redacted.slice(0, MAX_SPECIALIST_INPUT_CHARS - 16)}\n[truncated]` : redacted;
512	}
